def compact_log(log, k):
    stack = []  # [letter, how many stand together]
    for ch in log:
        if stack and stack[-1][0] == ch:
            stack[-1][1] += 1
            if stack[-1][1] == k:
                stack.pop()
        else:
            stack.append([ch, 1])
    return ''.join(ch * n for ch, n in stack)

